package app.ripple.mesh.core

import org.json.JSONObject
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test
import java.math.BigInteger
import java.security.KeyFactory
import java.security.KeyPair
import java.security.spec.ECPrivateKeySpec

/**
 * Conformance against protocol/test-vectors.json (generated by the Node reference
 * implementation). If these pass, Android and iOS agree byte-for-byte.
 */
class ProtocolVectorsTest {
    private val v: JSONObject = JSONObject(javaClass.getResourceAsStream("/test-vectors.json")!!.readBytes().toString(Charsets.UTF_8))

    private fun identityFromScalar(hex: String): Identity {
        val d = BigInteger(1, hex.hexToBytes())
        val priv = KeyFactory.getInstance("EC").generatePrivate(ECPrivateKeySpec(d, Crypto.p256Params))
        // Derive the public point via a scalar multiplication using the JDK: easiest is
        // to sign nothing and instead reconstruct from the known wire form in the vectors.
        val wire = when (hex) {
            v.getJSONObject("identities").getJSONObject("alice").getString("privateScalar") -> v.getJSONObject("identities").getJSONObject("alice").getString("publicKeyWire")
            v.getJSONObject("identities").getJSONObject("bob").getString("privateScalar") -> v.getJSONObject("identities").getJSONObject("bob").getString("publicKeyWire")
            else -> v.getJSONObject("directMessage").getString("ephemeralPublicKeyWire")
        }
        return Identity(priv, Crypto.publicKeyFromWire(wire.hexToBytes()))
    }

    private val alice by lazy { identityFromScalar(v.getJSONObject("identities").getJSONObject("alice").getString("privateScalar")) }
    private val bob by lazy { identityFromScalar(v.getJSONObject("identities").getJSONObject("bob").getString("privateScalar")) }

    private fun fragmentFrame(streamId: Int, index: Int, total: Int, payload: ByteArray = ByteArray(0)): ByteArray {
        val frame = ByteArray(Fragmenter.HEADER + payload.size)
        frame[0] = (streamId ushr 8).toByte(); frame[1] = streamId.toByte()
        frame[2] = index.toByte(); frame[3] = total.toByte()
        payload.copyInto(frame, Fragmenter.HEADER)
        return frame
    }

    @Test fun `node ids match`() {
        val ids = v.getJSONObject("identities")
        assertEquals(ids.getJSONObject("alice").getString("nodeId"), alice.nodeId.hex)
        assertEquals(ids.getJSONObject("bob").getString("nodeId"), bob.nodeId.hex)
        assertEquals(ids.getJSONObject("alice").getString("display"), alice.nodeId.display)
    }

    @Test fun `outbound payload and ECIES overhead limits are enforced`() {
        val maxDirectTextBytes = Protocol.MAX_PAYLOAD - (65 + 12 + 16)
        val maximumBroadcast = PacketFactory.broadcastText(alice, "x".repeat(Protocol.MAX_PAYLOAD))
        assertEquals(Protocol.MAX_PAYLOAD, maximumBroadcast.payload.size)
        val directText = "x".repeat(maxDirectTextBytes - 3) + "€"
        assertEquals(maxDirectTextBytes, directText.toByteArray(Charsets.UTF_8).size)
        val maximumDirect = PacketFactory.directText(alice, bob.nodeId, bob.publicKeyWire, directText)
        assertEquals(Protocol.MAX_PAYLOAD, maximumDirect.payload.size)

        try {
            PacketFactory.broadcastText(alice, "x".repeat(Protocol.MAX_PAYLOAD + 1))
            fail("oversized broadcast payload should be rejected")
        } catch (_: IllegalArgumentException) {}
        try {
            PacketFactory.directText(alice, bob.nodeId, bob.publicKeyWire, directText + "x")
            fail("oversized ECIES plaintext should be rejected before encryption")
        } catch (_: IllegalArgumentException) {}
    }

    @Test fun `private scalars really match the public keys`() {
        // ECDH(alice.priv, bob.pub) == ECDH(bob.priv, alice.pub) only if both key pairs are consistent.
        assertArrayEquals(Crypto.ecdh(alice.privateKey, bob.publicKey), Crypto.ecdh(bob.privateKey, alice.publicKey))
    }

    @Test fun `announce encodes identically and verifies`() {
        val a = v.getJSONObject("announce")
        val payload = Announce(alice.publicKeyWire, a.getString("name")).encode()
        assertEquals(a.getString("payload"), payload.toHex())

        val full = Packet.decode(a.getString("fullPacket").hexToBytes())
        assertEquals(a.getString("unsignedBytes"), full.encodeUnsigned().toHex())
        assertEquals(a.getString("signingDigest"), full.signingDigest().toHex())
        assertTrue(Crypto.verify(alice.publicKey, full.encodeUnsigned(), full.signature))

        val d = a.getJSONObject("decoded")
        assertEquals(PacketType.ANNOUNCE, full.type)
        assertEquals(d.getInt("ttl"), full.ttl)
        assertEquals(d.getString("timestamp"), full.timestamp.toString())
        assertEquals(d.getString("source"), full.source.hex)
        assertTrue(full.destination.isBroadcast)

        val dec = Announce.decode(full.payload)
        assertEquals(a.getString("name"), dec.name)
    }

    @Test fun `our own signatures verify and match the vector's digest`() {
        val a = v.getJSONObject("announce")
        val ref = Packet.decode(a.getString("fullPacket").hexToBytes())
        val mine = PacketFactory.build(alice, PacketType.ANNOUNCE, ref.payload, ttl = ref.ttl, messageId = ref.messageId, timestamp = ref.timestamp)
        assertEquals(a.getString("unsignedBytes"), mine.encodeUnsigned().toHex())
        assertTrue(Crypto.verify(alice.publicKey, mine.encodeUnsigned(), mine.signature))
        assertEquals(64, mine.signature.size)
    }

    @Test fun `ttl decrement does not change the signing digest`() {
        val b = v.getJSONObject("broadcastMessage")
        val p = Packet.decode(b.getString("fullPacket").hexToBytes())
        assertEquals(b.getString("signingDigestAfterTtlDecrement"), p.withTtl(p.ttl - 1).signingDigest().toHex())
        assertTrue(Crypto.verify(alice.publicKey, p.withTtl(1).encodeUnsigned(), p.signature))
        assertEquals(b.getString("text"), String(p.payload, Charsets.UTF_8))
    }

    @Test fun `ecies matches the vector step by step`() {
        val d = v.getJSONObject("directMessage")
        val messageId = Packet.decode(d.getString("fullPacket").hexToBytes()).messageId
        val eph = identityFromScalar(d.getString("ephemeralScalar"))
        assertEquals(d.getString("ephemeralPublicKeyWire"), eph.publicKeyWire.toHex())

        val shared = Crypto.ecdh(eph.privateKey, bob.publicKey)
        assertEquals(d.getString("ecdhSharedX"), shared.toHex())
        assertEquals(d.getString("hkdfKey"), Crypto.hkdf(shared, messageId, Protocol.HKDF_INFO, 32).toHex())

        val box = Crypto.encryptWith(
            KeyPair(eph.publicKey, eph.privateKey), bob.publicKeyWire, messageId, alice.nodeId, bob.nodeId,
            d.getString("plaintext").toByteArray(Charsets.UTF_8), d.getString("nonce").hexToBytes(),
        )
        assertEquals(d.getString("eciesPayload"), box.toHex())

        val plain = Crypto.decrypt(bob.privateKey, messageId, alice.nodeId, bob.nodeId, box)
        assertEquals(d.getString("plaintext"), String(plain, Charsets.UTF_8))
    }

    @Test fun `direct packet from vector decrypts for bob and not alice`() {
        val d = v.getJSONObject("directMessage")
        val p = Packet.decode(d.getString("fullPacket").hexToBytes())
        assertTrue(p.isEncrypted)
        assertTrue(Crypto.verify(alice.publicKey, p.encodeUnsigned(), p.signature))
        assertEquals(d.getString("plaintext"), String(Crypto.decrypt(bob.privateKey, p.messageId, p.source, p.destination, p.payload), Charsets.UTF_8))
        try { Crypto.decrypt(alice.privateKey, p.messageId, p.source, p.destination, p.payload); fail("alice must not decrypt") } catch (_: Exception) {}
    }

    @Test fun `ack vector`() {
        val p = Packet.decode(v.getJSONObject("ack").getString("fullPacket").hexToBytes())
        assertEquals(PacketType.ACK, p.type)
        assertEquals(bob.nodeId.hex, p.source.hex)
        assertEquals(alice.nodeId.hex, p.destination.hex)
        assertTrue(Crypto.verify(bob.publicKey, p.encodeUnsigned(), p.signature))
        assertEquals(v.getJSONObject("directMessage").getString("fullPacket").hexToBytes().let { Packet.decode(it).messageIdHex }, p.payload.toHex())
    }

    @Test fun `fragmentation vectors`() {
        val f = v.getJSONObject("fragmentation")
        val frames = Fragmenter.fragment(f.getString("input").hexToBytes(), f.getInt("frameSize"), f.getInt("streamId"))
        val expected = f.getJSONArray("frames")
        assertEquals(expected.length(), frames.size)
        for (i in frames.indices) assertEquals(expected.getString(i), frames[i].toHex())

        val r = Reassembler()
        var out: ByteArray? = null
        for (fr in frames.shuffled()) r.push(fr)?.let { out = it }
        assertEquals(f.getString("input"), out!!.toHex())

        val small = f.getJSONObject("small")
        val sf = Fragmenter.fragment(small.getString("input").hexToBytes(), small.getInt("frameSize"), small.getInt("streamId"))
        assertEquals(small.getJSONArray("frames").getString(0), sf.single().toHex())
    }

    @Test fun `fragmentation and reassembly reject packets above MAX_PACKET`() {
        assertEquals(16 * Fragmenter.MAX_FRAGMENTS, Fragmenter.maxPacketSize(20))
        assertTrue(Fragmenter.canFragment(16 * Fragmenter.MAX_FRAGMENTS, 20))
        assertFalse(Fragmenter.canFragment(16 * Fragmenter.MAX_FRAGMENTS + 1, 20))
        assertEquals(Protocol.MAX_PACKET, Fragmenter.maxPacketSize(23))
        assertTrue(Fragmenter.canFragment(Protocol.MAX_PACKET, 23))
        val maxPacket = ByteArray(Protocol.MAX_PACKET) { it.toByte() }
        val legacyFrames = Fragmenter.fragment(ByteArray(16 * Fragmenter.MAX_FRAGMENTS), frameSize = 20, streamId = 3)
        assertEquals(255, legacyFrames.size)
        assertTrue(legacyFrames.all { it.size <= 20 })
        val fullFrames = Fragmenter.fragment(maxPacket, frameSize = 23, streamId = 4)
        assertEquals(222, fullFrames.size)
        assertTrue(fullFrames.all { it.size <= 23 })
        var rebuilt: ByteArray? = null
        val reassembler = Reassembler()
        fullFrames.forEach { reassembler.push(it)?.let { packet -> rebuilt = packet } }
        assertArrayEquals(maxPacket, rebuilt!!)
        try {
            Fragmenter.fragment(ByteArray(16 * Fragmenter.MAX_FRAGMENTS + 1), frameSize = 20, streamId = 1)
            fail("packet too large for a legacy MTU should not be fragmented")
        } catch (_: IllegalArgumentException) {}
        try {
            Fragmenter.fragment(ByteArray(Protocol.MAX_PACKET + 1), frameSize = 512, streamId = 1)
            fail("oversized packet should not be fragmented")
        } catch (_: IllegalArgumentException) {}

        val r = Reassembler()
        assertNull(r.push(fragmentFrame(1, 0, 1, ByteArray(Protocol.MAX_PACKET + 1))))

        val multipart = Reassembler()
        assertNull(multipart.push(fragmentFrame(2, 0, 2, ByteArray(Protocol.MAX_PACKET))))
        assertNull(multipart.push(fragmentFrame(2, 1, 2, byteArrayOf(1))))
    }

    @Test fun `reassembly caps active streams and aggregate buffered bytes`() {
        var now = 0L
        val capped = Reassembler(clock = { now })
        for (id in 0 until Protocol.MAX_REASSEMBLY_STREAMS) {
            assertNull(capped.push(fragmentFrame(id, 0, 2, byteArrayOf(id.toByte()))))
        }
        assertNull(capped.push(fragmentFrame(99, 0, 2, byteArrayOf(99))))
        assertNull(capped.push(fragmentFrame(99, 1, 2, byteArrayOf(100))))
        assertArrayEquals(byteArrayOf(0, 1), capped.push(fragmentFrame(0, 1, 2, byteArrayOf(1)))!!)
        assertNull(capped.push(fragmentFrame(99, 0, 2, byteArrayOf(99))))
        assertArrayEquals(byteArrayOf(99, 100), capped.push(fragmentFrame(99, 1, 2, byteArrayOf(100)))!!)

        var adversarialNow = 0L
        val worstCase = Reassembler(ttlMs = 1_000L, clock = { adversarialNow })
        for (id in 0 until Protocol.MAX_REASSEMBLY_STREAMS) {
            assertNull(worstCase.push(fragmentFrame(id, 0, 255)))
        }
        assertNull(worstCase.push(fragmentFrame(99, 0, 2, byteArrayOf(99))))
        assertNull(worstCase.push(fragmentFrame(99, 1, 2, byteArrayOf(100))))
        adversarialNow = 1_000L
        assertNull(worstCase.push(fragmentFrame(100, 0, 2, byteArrayOf(10))))
        assertArrayEquals(byteArrayOf(10, 11), worstCase.push(fragmentFrame(100, 1, 2, byteArrayOf(11)))!!)

        val buffered = Reassembler(clock = { now })
        val maxPart = ByteArray(Protocol.MAX_PACKET) { 0x61.toByte() }
        for (id in 0 until 7) assertNull(buffered.push(fragmentFrame(id, 0, 2, maxPart)))
        val remaining = Protocol.MAX_REASSEMBLY_BYTES - 7 * Protocol.MAX_PACKET
        val lastPart = ByteArray(remaining) { 0x62.toByte() }
        assertNull(buffered.push(fragmentFrame(7, 0, 2, lastPart)))
        assertArrayEquals(lastPart, buffered.push(fragmentFrame(7, 1, 2))!!)

        assertNull(buffered.push(fragmentFrame(7, 0, 2, lastPart)))
        assertNull(buffered.push(fragmentFrame(7, 1, 2, byteArrayOf(0x63))))
        assertArrayEquals(maxPart, buffered.push(fragmentFrame(0, 1, 2))!!)
        assertNull(buffered.push(fragmentFrame(7, 1, 2, byteArrayOf(0x63))))
        val expected = lastPart + byteArrayOf(0x63)
        assertArrayEquals(expected, buffered.push(fragmentFrame(7, 0, 2, lastPart))!!)
    }

    @Test fun `reassembly expires partial streams at a fixed deadline`() {
        var now = 0L
        val r = Reassembler(ttlMs = 1_000L, clock = { now })
        assertNull(r.push(fragmentFrame(1, 0, 2, byteArrayOf(1))))
        now = 999L
        assertArrayEquals(byteArrayOf(1, 2), r.push(fragmentFrame(1, 1, 2, byteArrayOf(2)))!!)
        now = 2_000L
        assertNull(r.push(fragmentFrame(2, 0, 2, byteArrayOf(3))))
        now = 3_000L
        assertNull(r.push(fragmentFrame(2, 1, 2, byteArrayOf(4))))
        now = 3_001L
        assertArrayEquals(byteArrayOf(5, 4), r.push(fragmentFrame(2, 0, 2, byteArrayOf(5)))!!)
    }

    @Test fun `high-bit timestamp vector preserves unsigned wire bits`() {
        val high = v.getJSONObject("highBitTimestamp")
        val packet = Packet.decode(high.getString("fullPacket").hexToBytes())
        assertEquals(Long.MIN_VALUE, packet.timestamp)
        assertArrayEquals(high.getString("fullPacket").hexToBytes(), packet.encode())
        assertTrue(Crypto.verify(alice.publicKey, packet.encodeUnsigned(), packet.signature))
    }

    @Test fun `invalid packets are rejected`() {
        val bad = v.getJSONObject("invalid")
        for (key in listOf("wrongVersion", "truncated", "ttl8", "ttl255", "directWithoutEncryption", "broadcastWithEncryption")) {
            try { Packet.decode(bad.getString(key).hexToBytes()); fail("$key should not decode") } catch (_: ProtocolException) {}
        }
        val tampered = Packet.decode(bad.getString("tamperedPayload").hexToBytes())
        assertFalse(Crypto.verify(alice.publicKey, tampered.encodeUnsigned(), tampered.signature))
    }

    @Test fun `packet creation rejects MESSAGE encryption mode mismatches`() {
        try {
            PacketFactory.build(alice, PacketType.MESSAGE, byteArrayOf(1), destination = bob.nodeId)
            fail("a unicast MESSAGE must be encrypted")
        } catch (_: ProtocolException) {}
        try {
            PacketFactory.build(alice, PacketType.MESSAGE, byteArrayOf(1), flags = Flags.ENCRYPTED)
            fail("a broadcast MESSAGE must not be encrypted")
        } catch (_: ProtocolException) {}
    }

    @Test fun `packet creation rejects ttl above MAX_TTL`() {
        try {
            PacketFactory.build(alice, PacketType.MESSAGE, byteArrayOf(1), ttl = Protocol.MAX_TTL + 1)
            fail("ttl above MAX_TTL should not be encoded")
        } catch (_: IllegalArgumentException) {}
    }

    // ---- Phase 2: SOS beacon payload (PROTOCOL.md §2.2) --------------------------------

    @Test fun `sos beacon with opted-in gps encodes identically to the vector`() {
        val s = v.getJSONObject("sos")
        val loc = s.getJSONObject("location")
        val payload = SosCodec.encode(s.getString("text"), SosLocation(loc.getInt("latE7"), loc.getInt("lngE7"), loc.getInt("accuracyMeters")))
        assertEquals(s.getString("payload"), payload.toHex())
        val dec = SosCodec.decode(payload)
        assertEquals(s.getString("text"), dec.text)
        assertEquals(loc.getInt("latE7"), dec.location!!.latE7)
        assertEquals(loc.getInt("lngE7"), dec.location!!.lngE7)   // negative longitude round-trips
        assertEquals(loc.getInt("accuracyMeters"), dec.location!!.accuracyMeters)
    }

    @Test fun `sos beacon without gps omits the location bytes entirely`() {
        val s = v.getJSONObject("sos")
        val payload = SosCodec.encode(s.getString("noLocationText"), null)
        assertEquals(s.getString("noLocationPayload"), payload.toHex())
        val dec = SosCodec.decode(payload)
        assertEquals(s.getString("noLocationText"), dec.text)
        assertNull(dec.location)
    }

    @Test fun `sos beacon packet is type SOS, broadcast, and verifies`() {
        val s = v.getJSONObject("sos")
        val full = Packet.decode(s.getString("fullPacket").hexToBytes())
        assertEquals(PacketType.SOS, full.type)
        assertEquals(4, full.type.code)
        assertTrue(full.destination.isBroadcast)
        assertEquals(s.getString("signingDigest"), full.signingDigest().toHex())
        assertTrue(Crypto.verify(alice.publicKey, full.encodeUnsigned(), full.signature))
        val dec = SosCodec.decode(full.payload)
        assertEquals(s.getString("text"), dec.text)
        assertEquals(s.getJSONObject("location").getInt("latE7"), dec.location!!.latE7)
    }

    @Test fun `sos beacon decoded header matches the vector`() {
        val s = v.getJSONObject("sos")
        val d = s.getJSONObject("decoded")
        val full = Packet.decode(s.getString("fullPacket").hexToBytes())
        assertEquals(d.getInt("type"), full.type.code)
        assertEquals(d.getInt("ttl"), full.ttl)
        assertEquals(d.getString("messageId"), full.messageIdHex)
        assertEquals(d.getString("source"), full.source.hex)
        assertEquals(d.getInt("payloadLength"), full.payload.size)
        assertEquals(s.getString("payload"), full.payload.toHex())
    }
}
